     1→import { useRef, useCallback, useEffect, useState } from 'react';
     2→import { Audio, type AVPlaybackStatus } from 'expo-av';
     3→
     4→export type AudioPlayerState = {
     5→  isPlaying: boolean;
     6→  positionMs: number;
     7→  durationMs: number;
     8→};
     9→
    10→type UseAudioPlayerReturn = {
    11→  // Narration
    12→  narrationState: AudioPlayerState;
    13→  loadNarration: (uri: string) => Promise<void>;
    14→  playNarration: () => Promise<void>;
    15→  pauseNarration: () => Promise<void>;
    16→  seekNarration: (positionMs: number) => Promise<void>;
    17→  setNarrationVolume: (volume: number) => Promise<void>;
    18→  // Soundscape
    19→  soundscapeState: AudioPlayerState;
    20→  loadSoundscape: (uri: string) => Promise<void>;
    21→  playSoundscape: () => Promise<void>;
    22→  pauseSoundscape: () => Promise<void>;
    23→  setSoundscapeVolume: (volume: number) => Promise<void>;
    24→  // Crossfade
    25→  crossfadeSoundscape: (newUri: string, duration?: number) => Promise<void>;
    26→  fadeOutSoundscape: (duration?: number) => Promise<void>;
    27→  // Cleanup
    28→  cleanup: () => Promise<void>;
    29→};
    30→
    31→export function useAudioPlayer(): UseAudioPlayerReturn {
    32→  const narrationRef = useRef<Audio.Sound | null>(null);
    33→  const soundscapeRef = useRef<Audio.Sound | null>(null);
    34→  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
    35→
    36→  const [narrationState, setNarrationState] = useState<AudioPlayerState>({
    37→    isPlaying: false,
    38→    positionMs: 0,
    39→    durationMs: 0,
    40→  });
    41→
    42→  const [soundscapeState, setSoundscapeState] = useState<AudioPlayerState>({
    43→    isPlaying: false,
    44→    positionMs: 0,
    45→    durationMs: 0,
    46→  });
    47→
    48→  // Configure audio mode for background playback
    49→  useEffect(() => {
    50→    Audio.setAudioModeAsync({
    51→      playsInSilentModeIOS: true,
    52→      staysActiveInBackground: true,
    53→      shouldDuckAndroid: true,
    54→    });
    55→  }, []);
    56→
    57→  const handleNarrationStatus = useCallback((status: AVPlaybackStatus) => {
    58→    if (!status.isLoaded) return;
    59→    setNarrationState({
    60→      isPlaying: status.isPlaying,
    61→      positionMs: status.positionMillis,
    62→      durationMs: status.durationMillis ?? 0,
    63→    });
    64→  }, []);
    65→
    66→  const handleSoundscapeStatus = useCallback((status: AVPlaybackStatus) => {
    67→    if (!status.isLoaded) return;
    68→    setSoundscapeState({
    69→      isPlaying: status.isPlaying,
    70→      positionMs: status.positionMillis,
    71→      durationMs: status.durationMillis ?? 0,
    72→    });
    73→  }, []);
    74→
    75→  // Narration controls
    76→  const loadNarration = useCallback(async (uri: string) => {
    77→    if (narrationRef.current) {
    78→      await narrationRef.current.unloadAsync();
    79→    }
    80→    const { sound } = await Audio.Sound.createAsync(
    81→      { uri },
    82→      { shouldPlay: false, progressUpdateIntervalMillis: 50 },
    83→      handleNarrationStatus
    84→    );
    85→    narrationRef.current = sound;
    86→  }, [handleNarrationStatus]);
    87→
    88→  const playNarration = useCallback(async () => {
    89→    await narrationRef.current?.playAsync();
    90→  }, []);
    91→
    92→  const pauseNarration = useCallback(async () => {
    93→    await narrationRef.current?.pauseAsync();
    94→  }, []);
    95→
    96→  const seekNarration = useCallback(async (positionMs: number) => {
    97→    await narrationRef.current?.setPositionAsync(positionMs);
    98→  }, []);
    99→
   100→  const setNarrationVolume = useCallback(async (volume: number) => {
   101→    await narrationRef.current?.setVolumeAsync(volume);
   102→  }, []);
   103→
   104→  // Soundscape controls
   105→  const loadSoundscape = useCallback(async (uri: string) => {
   106→    if (soundscapeRef.current) {
   107→      await soundscapeRef.current.unloadAsync();
   108→    }
   109→    const { sound } = await Audio.Sound.createAsync(
   110→      { uri },
   111→      { shouldPlay: false, isLooping: true, volume: 0.6 },
   112→      handleSoundscapeStatus
   113→    );
   114→    soundscapeRef.current = sound;
   115→  }, [handleSoundscapeStatus]);
   116→
   117→  const playSoundscape = useCallback(async () => {
   118→    await soundscapeRef.current?.playAsync();
   119→  }, []);
   120→
   121→  const pauseSoundscape = useCallback(async () => {
   122→    await soundscapeRef.current?.pauseAsync();
   123→  }, []);
   124→
   125→  const setSoundscapeVolume = useCallback(async (volume: number) => {
   126→    await soundscapeRef.current?.setVolumeAsync(volume);
   127→  }, []);
   128→
   129→  // Fade out over duration
   130→  const fadeOutSoundscape = useCallback(async (duration: number = 3000) => {
   131→    const sound = soundscapeRef.current;
   132→    if (!sound) return;
   133→
   134→    const status = await sound.getStatusAsync();
   135→    if (!status.isLoaded) return;
   136→
   137→    const startVolume = status.volume;
   138→    const steps = 20;
   139→    const stepDuration = duration / steps;
   140→    const volumeStep = startVolume / steps;
   141→    let currentStep = 0;
   142→
   143→    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
   144→
   145→    return new Promise<void>((resolve) => {
   146→      fadeIntervalRef.current = setInterval(async () => {
   147→        currentStep++;
   148→        const newVolume = Math.max(0, startVolume - volumeStep * currentStep);
   149→        await sound.setVolumeAsync(newVolume);
   150→
   151→        if (currentStep >= steps) {
   152→          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
   153→          await sound.pauseAsync();
   154→          resolve();
   155→        }
   156→      }, stepDuration);
   157→    });
   158→  }, []);
   159→
   160→  // Crossfade: fade out current, load new, fade in
   161→  const crossfadeSoundscape = useCallback(async (newUri: string, duration: number = 1500) => {
   162→    const oldSound = soundscapeRef.current;
   163→
   164→    // Load new sound at volume 0
   165→    const { sound: newSound } = await Audio.Sound.createAsync(
   166→      { uri: newUri },
   167→      { shouldPlay: true, isLooping: true, volume: 0 },
   168→      handleSoundscapeStatus
   169→    );
   170→
   171→    // Fade out old, fade in new simultaneously
   172→    const steps = 15;
   173→    const stepDuration = duration / steps;
   174→    let currentStep = 0;
   175→
   176→    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
   177→
   178→    return new Promise<void>((resolve) => {
   179→      fadeIntervalRef.current = setInterval(async () => {
   180→        currentStep++;
   181→        const progress = currentStep / steps;
   182→
   183→        // Fade in new
   184→        await newSound.setVolumeAsync(0.6 * progress);
   185→
   186→        // Fade out old
   187→        if (oldSound) {
   188→          try {
   189→            await oldSound.setVolumeAsync(0.6 * (1 - progress));
   190→          } catch {
   191→            // Old sound may already be unloaded
   192→          }
   193→        }
   194→
   195→        if (currentStep >= steps) {
   196→          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
   197→
   198→          // Cleanup old
   199→          if (oldSound) {
   200→            try {
   201→              await oldSound.unloadAsync();
   202→            } catch {
   203→              // Ignore
   204→            }
   205→          }
   206→
   207→          soundscapeRef.current = newSound;
   208→          resolve();
   209→        }
   210→      }, stepDuration);
   211→    });
   212→  }, [handleSoundscapeStatus]);
   213→
   214→  // Cleanup all audio
   215→  const cleanup = useCallback(async () => {
   216→    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
   217→
   218→    if (narrationRef.current) {
   219→      try {
   220→        await narrationRef.current.unloadAsync();
   221→      } catch { /* ignore */ }
   222→      narrationRef.current = null;
   223→    }
   224→
   225→    if (soundscapeRef.current) {
   226→      try {
   227→        await soundscapeRef.current.unloadAsync();
   228→      } catch { /* ignore */ }
   229→      soundscapeRef.current = null;
   230→    }
   231→
   232→    setNarrationState({ isPlaying: false, positionMs: 0, durationMs: 0 });
   233→    setSoundscapeState({ isPlaying: false, positionMs: 0, durationMs: 0 });
   234→  }, []);
   235→
   236→  // Cleanup on unmount
   237→  useEffect(() => {
   238→    return () => {
   239→      cleanup();
   240→    };
   241→  }, [cleanup]);
   242→
   243→  return {
   244→    narrationState,
   245→    loadNarration,
   246→    playNarration,
   247→    pauseNarration,
   248→    seekNarration,
   249→    setNarrationVolume,
   250→    soundscapeState,
   251→    loadSoundscape,
   252→    playSoundscape,
   253→    pauseSoundscape,
   254→    setSoundscapeVolume,
   255→    crossfadeSoundscape,
   256→    fadeOutSoundscape,
   257→    cleanup,
   258→  };
   259→}
   260→

