     1→import { useEffect, useRef, useState, useCallback } from 'react';
     2→import { useAudioPlayer, type AudioPlayerState } from './useAudioPlayer';
     3→import { useLocalPreferences } from './useLocalPreferences';
     4→import type { PageData } from '@/types';
     5→
     6→type UseReaderAudioProps = {
     7→  pageData: PageData | undefined;
     8→  bookId: string;
     9→};
    10→
    11→type UseReaderAudioReturn = {
    12→  isNarrationActive: boolean;
    13→  isSoundscapeActive: boolean;
    14→  narrationState: AudioPlayerState;
    15→  soundscapeState: AudioPlayerState;
    16→  toggleNarration: () => Promise<void>;
    17→  toggleSoundscape: () => Promise<void>;
    18→  loadNarration: (url: string) => Promise<void>;
    19→  loadSoundscape: (url: string) => Promise<void>;
    20→  cleanup: () => void;
    21→};
    22→
    23→export function useReaderAudio({ pageData }: UseReaderAudioProps): UseReaderAudioReturn {
    24→  const {
    25→    narrationState,
    26→    loadNarration: loadNarrationAudio,
    27→    playNarration,
    28→    pauseNarration,
    29→    soundscapeState,
    30→    loadSoundscape: loadSoundscapeAudio,
    31→    playSoundscape,
    32→    pauseSoundscape,
    33→    crossfadeSoundscape,
    34→    fadeOutSoundscape,
    35→    cleanup: cleanupAudio,
    36→  } = useAudioPlayer();
    37→
    38→  const { preferences } = useLocalPreferences();
    39→
    40→  const [isNarrationActive, setIsNarrationActive] = useState(false);
    41→  const [isSoundscapeActive, setIsSoundscapeActive] = useState(false);
    42→
    43→  const introFadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    44→  const introFadedPages = useRef(new Set<number>());
    45→  const prevSoundscapeUrl = useRef<string | null>(null);
    46→
    47→  const currentPage = pageData?.pageNumber ?? 1;
    48→
    49→  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
    50→  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
    51→  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl;
    52→  const soundscapeUrl = soundscapeAssignment?.audioUrl;
    53→
    54→  // Load narration audio when page changes
    55→  useEffect(() => {
    56→    if (narrationUrl) {
    57→      loadNarrationAudio(narrationUrl).then(() => {
    58→        if (isNarrationActive) {
    59→          playNarration();
    60→        }
    61→      });
    62→    }
    63→    // eslint-disable-next-line react-hooks/exhaustive-deps
    64→  }, [narrationUrl]);
    65→
    66→  // Handle soundscape changes with crossfade
    67→  useEffect(() => {
    68→    if (!soundscapeUrl) return;
    69→
    70→    if (prevSoundscapeUrl.current && prevSoundscapeUrl.current !== soundscapeUrl && isSoundscapeActive) {
    71→      crossfadeSoundscape(soundscapeUrl);
    72→    } else if (!prevSoundscapeUrl.current || prevSoundscapeUrl.current !== soundscapeUrl) {
    73→      loadSoundscapeAudio(soundscapeUrl).then(() => {
    74→        if (isSoundscapeActive) playSoundscape();
    75→      });
    76→    }
    77→    prevSoundscapeUrl.current = soundscapeUrl;
    78→    // eslint-disable-next-line react-hooks/exhaustive-deps
    79→  }, [soundscapeUrl]);
    80→
    81→  // Intro-only mode: fade out after 10 seconds
    82→  useEffect(() => {
    83→    if (introFadeTimerRef.current) {
    84→      clearTimeout(introFadeTimerRef.current);
    85→      introFadeTimerRef.current = null;
    86→    }
    87→
    88→    if (
    89→      preferences.soundscapeMode === 'intro-only' &&
    90→      isSoundscapeActive &&
    91→      soundscapeUrl &&
    92→      !introFadedPages.current.has(currentPage)
    93→    ) {
    94→      introFadeTimerRef.current = setTimeout(() => {
    95→        introFadedPages.current.add(currentPage);
    96→        fadeOutSoundscape(3000).then(() => {
    97→          setIsSoundscapeActive(false);
    98→        });
    99→      }, 10000);
   100→    }
   101→
   102→    return () => {
   103→      if (introFadeTimerRef.current) clearTimeout(introFadeTimerRef.current);
   104→    };
   105→  }, [currentPage, preferences.soundscapeMode, isSoundscapeActive, soundscapeUrl, fadeOutSoundscape]);
   106→
   107→  // Cleanup on unmount
   108→  useEffect(() => {
   109→    return () => {
   110→      cleanupAudio();
   111→    };
   112→    // eslint-disable-next-line react-hooks/exhaustive-deps
   113→  }, []);
   114→
   115→  const toggleNarration = useCallback(async () => {
   116→    if (isNarrationActive) {
   117→      await pauseNarration();
   118→      setIsNarrationActive(false);
   119→    } else if (narrationUrl) {
   120→      await playNarration();
   121→      setIsNarrationActive(true);
   122→    }
   123→  }, [isNarrationActive, narrationUrl, playNarration, pauseNarration]);
   124→
   125→  const toggleSoundscape = useCallback(async () => {
   126→    if (isSoundscapeActive) {
   127→      await pauseSoundscape();
   128→      setIsSoundscapeActive(false);
   129→    } else if (soundscapeUrl) {
   130→      await playSoundscape();
   131→      setIsSoundscapeActive(true);
   132→    }
   133→  }, [isSoundscapeActive, soundscapeUrl, playSoundscape, pauseSoundscape]);
   134→
   135→  const loadNarration = useCallback(
   136→    async (url: string) => {
   137→      await loadNarrationAudio(url);
   138→    },
   139→    [loadNarrationAudio]
   140→  );
   141→
   142→  const loadSoundscape = useCallback(
   143→    async (url: string) => {
   144→      await loadSoundscapeAudio(url);
   145→    },
   146→    [loadSoundscapeAudio]
   147→  );
   148→
   149→  const cleanup = useCallback(() => {
   150→    if (introFadeTimerRef.current) {
   151→      clearTimeout(introFadeTimerRef.current);
   152→      introFadeTimerRef.current = null;
   153→    }
   154→    cleanupAudio();
   155→  }, [cleanupAudio]);
   156→
   157→  return {
   158→    isNarrationActive,
   159→    isSoundscapeActive,
   160→    narrationState,
   161→    soundscapeState,
   162→    toggleNarration,
   163→    toggleSoundscape,
   164→    loadNarration,
   165→    loadSoundscape,
   166→    cleanup,
   167→  };
   168→}
   169→

