     1→import React from 'react';
     2→import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
     3→import { BlurView } from 'expo-blur';
     4→import Animated, {
     5→  useAnimatedStyle,
     6→  withTiming,
     7→} from 'react-native-reanimated';
     8→import { useSafeAreaInsets } from 'react-native-safe-area-context';
     9→import { fonts } from '@/lib/theme';
    10→
    11→type Props = {
    12→  hasNarration: boolean;
    13→  hasSoundscape: boolean;
    14→  isNarrationPlaying: boolean;
    15→  isSoundscapePlaying: boolean;
    16→  onToggleNarration: () => void;
    17→  onToggleSoundscape: () => void;
    18→  isVisible?: boolean;
    19→};
    20→
    21→export const AudioControls = React.memo(function AudioControls({
    22→  hasNarration,
    23→  hasSoundscape,
    24→  isNarrationPlaying,
    25→  isSoundscapePlaying,
    26→  onToggleNarration,
    27→  onToggleSoundscape,
    28→  isVisible = true,
    29→}: Props) {
    30→  const insets = useSafeAreaInsets();
    31→  const hasAudio = hasNarration || hasSoundscape;
    32→  const shouldShow = hasAudio && isVisible;
    33→
    34→  const containerStyle = useAnimatedStyle(() => ({
    35→    opacity: withTiming(shouldShow ? 1 : 0, { duration: 250 }),
    36→    transform: [{ translateY: withTiming(shouldShow ? 0 : 20, { duration: 250 }) }],
    37→  }));
    38→
    39→  return (
    40→    <Animated.View
    41→      style={[
    42→        styles.container,
    43→        { bottom: Math.max(24, insets.bottom + 8) },
    44→        containerStyle,
    45→      ]}
    46→      pointerEvents={shouldShow ? 'auto' : 'none'}
    47→    >
    48→      <BlurView
    49→        intensity={50}
    50→        tint="dark"
    51→        style={styles.backgroundBlur}
    52→      >
    53→        <View style={styles.pillRow}>
    54→          {hasNarration && (
    55→            <TouchableOpacity onPress={onToggleNarration} activeOpacity={0.7} hitSlop={20}>
    56→              <BlurView
    57→                intensity={30}
    58→                tint="dark"
    59→                style={[
    60→                  styles.pill,
    61→                  isNarrationPlaying && styles.pillActiveNarration,
    62→                ]}
    63→              >
    64→                <Text style={styles.pillEmoji}>
    65→                  {isNarrationPlaying ? '\u{23F8}' : '\u{1F3A4}'}
    66→                </Text>
    67→                <Text
    68→                  style={[
    69→                    styles.pillText,
    70→                    {
    71→                      color: isNarrationPlaying ? '#ffffff' : 'rgba(255,255,255,0.85)',
    72→                      fontFamily: fonts.sans,
    73→                    },
    74→                  ]}
    75→                >
    76→                  {isNarrationPlaying ? 'Pause' : 'Read'}
    77→                </Text>
    78→              </BlurView>
    79→            </TouchableOpacity>
    80→          )}
    81→
    82→          {hasSoundscape && (
    83→            <TouchableOpacity onPress={onToggleSoundscape} activeOpacity={0.7} hitSlop={20}>
    84→              <BlurView
    85→                intensity={30}
    86→                tint="dark"
    87→                style={[
    88→                  styles.pill,
    89→                  isSoundscapePlaying && styles.pillActiveSoundscape,
    90→                ]}
    91→              >
    92→                <Text style={styles.pillEmoji}>
    93→                  {isSoundscapePlaying ? '\u{1F50A}' : '\u{1F3B5}'}
    94→                </Text>
    95→                <Text
    96→                  style={[
    97→                    styles.pillText,
    98→                    {
    99→                      color: isSoundscapePlaying ? '#ffffff' : 'rgba(255,255,255,0.85)',
   100→                      fontFamily: fonts.sans,
   101→                    },
   102→                  ]}
   103→                >
   104→                  {isSoundscapePlaying ? 'Mute' : 'Sound'}
   105→                </Text>
   106→              </BlurView>
   107→            </TouchableOpacity>
   108→          )}
   109→        </View>
   110→      </BlurView>
   111→    </Animated.View>
   112→  );
   113→});
   114→
   115→const styles = StyleSheet.create({
   116→  container: {
   117→    position: 'absolute',
   118→    left: 0,
   119→    right: 0,
   120→    zIndex: 40,
   121→    alignItems: 'center',
   122→    paddingHorizontal: 16,
   123→  },
   124→  backgroundBlur: {
   125→    flexDirection: 'row',
   126→    alignItems: 'center',
   127→    paddingHorizontal: 12,
   128→    paddingVertical: 10,
   129→    borderRadius: 32,
   130→    overflow: 'hidden',
   131→    borderWidth: 1,
   132→    borderColor: 'rgba(255,255,255,0.1)',
   133→  },
   134→  pillRow: {
   135→    flexDirection: 'row',
   136→    gap: 10,
   137→  },
   138→  pill: {
   139→    flexDirection: 'row',
   140→    alignItems: 'center',
   141→    gap: 8,
   142→    paddingVertical: 14,
   143→    paddingHorizontal: 20,
   144→    borderRadius: 24,
   145→    borderWidth: 1,
   146→    borderColor: 'rgba(255,255,255,0.12)',
   147→    overflow: 'hidden',
   148→    minHeight: 52,
   149→    minWidth: 100,
   150→    justifyContent: 'center',
   151→  },
   152→  pillActiveNarration: {
   153→    backgroundColor: 'rgba(249, 115, 22, 0.9)',
   154→    borderColor: 'rgba(251, 146, 60, 0.7)',
   155→  },
   156→  pillActiveSoundscape: {
   157→    backgroundColor: 'rgba(20, 184, 166, 0.9)',
   158→    borderColor: 'rgba(45, 212, 191, 0.7)',
   159→  },
   160→  pillEmoji: {
   161→    fontSize: 18,
   162→  },
   163→  pillText: {
