   187→  // ═══════════════════════════════════════════════════════════════
   188→
   189→  useEffect(() => {
   190→    if (tutorialCheckedRef.current || isLoading) return;
   191→    
   192→    const checkTutorial = async () => {
   193→      const hasSeen = await hasSeenGestureTutorial();
   194→      if (!hasSeen) {
   195→        setShowTutorial(true);
   196→      }
   197→      tutorialCheckedRef.current = true;
   198→    };
   199→    
   200→    checkTutorial();
   201→  }, [isLoading]);
   202→
   203→  const handleTutorialComplete = useCallback(() => {
   204→    setShowTutorial(false);
   205→    markGestureTutorialSeen();
   206→  }, []);
   207→
   208→  // ═══════════════════════════════════════════════════════════════
   209→  // CLEANUP
   210→  // ═══════════════════════════════════════════════════════════════
   211→
   212→  // Cleanup on unmount
   213→  useEffect(() => {
   214→    return () => {
   215→      cleanup();
   216→    };
   217→    // eslint-disable-next-line react-hooks/exhaustive-deps
   218→  }, []);
   219→
   220→  const handleClose = useCallback(() => {
   221→    cleanup();
   222→    router.back();
   223→  }, [router, cleanup]);
   224→
   225→  // ═══════════════════════════════════════════════════════════════
   226→  // EDGE TAP NAVIGATION
   227→  // ═══════════════════════════════════════════════════════════════
   228→
   229→  const goToPreviousPage = useCallback(() => {
   230→    if (activeIndex > 0) {
   231→      const newIndex = activeIndex - 1;
   232→      setActiveIndex(newIndex);
   233→      activeIndexShared.value = newIndex;
   234→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   235→    }
   236→  }, [activeIndex, activeIndexShared]);
   237→
   238→  const goToNextPage = useCallback(() => {
   239→    if (activeIndex < totalPages - 1) {
   240→      const newIndex = activeIndex + 1;
   241→      setActiveIndex(newIndex);
   242→      activeIndexShared.value = newIndex;
   243→      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   244→    }
   245→  }, [activeIndex, totalPages, activeIndexShared]);
   246→
   247→  // Animated styles for UI visibility
   248→  const topBarAnimatedStyle = useAnimatedStyle(() => ({
   249→    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
   250→  }));
   251→
   252→  const audioControlsAnimatedStyle = useAnimatedStyle(() => ({
   253→    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
   254→  }));
   255→
   256→  const tapHintAnimatedStyle = useAnimatedStyle(() => ({
   257→    opacity: withTiming(isUIVisible ? 0 : 0.5, { duration: UI_ANIMATION_DURATION }),
   258→  }));
   259→
   260→  // ═══════════════════════════════════════════════════════════════
   261→  // VISIBLE PAGES (virtualization window of ±1)
   262→  // Optimized: O(1) slice instead of O(n) filter + indexOf
   263→  // ═══════════════════════════════════════════════════════════════
   264→
   265→  const visiblePages = useMemo(() => {
   266→    const start = Math.max(0, activeIndex - 1);
   267→    const end = Math.min(pages.length - 1, activeIndex + 1);
   268→    const result: { page: typeof pages[0]; index: number }[] = [];
   269→    for (let i = start; i <= end; i++) {
   270→      result.push({ page: pages[i], index: i });
   271→    }
   272→    return result;
   273→  }, [pages, activeIndex]);
   274→
   275→  // ═══════════════════════════════════════════════════════════════
   276→  // RENDER
   277→  // ═══════════════════════════════════════════════════════════════
   278→
   279→  if (isLoading) {
   280→    return <ReaderSkeleton />;
   281→  }
   282→
   283→  if (error || !readerData) {
   284→    return (
   285→      <View style={[styles.centered, { backgroundColor: colors.readerBg }]}>
   286→        <Text style={[styles.errorTitle, { color: colors.error, fontFamily: fonts.sans }]}>
   287→          Oops!
   288→        </Text>
   289→        <Text style={[styles.errorText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
   290→          {error?.message || 'Book not found'}
   291→        </Text>
   292→        <View style={styles.errorButtonsContainer}>
   293→          <TouchableOpacity
   294→            style={[styles.primaryButton, { backgroundColor: colors.readerProgressBarFill }]}
   295→            onPress={() => refetch()}
   296→            activeOpacity={0.8}
   297→          >
   298→            <Text style={[styles.primaryButtonText, { color: colors.readerBg, fontFamily: fonts.sans }]}>
   299→              Try Again
   300→            </Text>
   301→          </TouchableOpacity>
   302→          <TouchableOpacity
   303→            style={[styles.secondaryButton, { borderColor: colors.readerTextSecondary }]}
   304→            onPress={() => router.back()}
   305→            activeOpacity={0.8}
   306→          >
   307→            <Text style={[styles.secondaryButtonText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
   308→              Go Back
   309→            </Text>
   310→          </TouchableOpacity>
   311→        </View>
   312→      </View>
   313→    );
   314→  }
   315→
   316→  return (
   317→    <View style={[styles.container, { backgroundColor: colors.readerBg }]}>
   318→      <GestureDetector gesture={composedGesture}>
   319→        <View style={styles.pagerContainer}>
   320→          {visiblePages.map(({ page, index }) => (
   321→            <PageLayer
   322→              key={page.id}
   323→              page={page}
   324→              pageIndex={index}
   325→              activeIndex={activeIndex}
   326→              narrationTimestamps={page.narrationTimestamps ?? null}
   327→              currentPositionMs={narrationState.positionMs}
   328→              isNarrationPlaying={isNarrationActive && narrationState.isPlaying}
   329→              usePageAnimatedStyle={getPageAnimatedStyle}
   330→            />
   331→          ))}
   332→        </View>
   333→      </GestureDetector>
   334→
   335→      {/* Floating UI */}
   336→      <Animated.View
   337→        style={[styles.topBarContainer, topBarAnimatedStyle]}
   338→        pointerEvents={isUIVisible ? 'auto' : 'none'}
   339→      >
   340→        <ReaderTopBar
   341→          progressPercent={progressPercent}
   342→          currentPage={currentPage}
   343→          totalPages={totalPages}
   344→          onClose={handleClose}
   345→          onSettings={() => setShowSettings(true)}
   346→        />
   347→      </Animated.View>
   348→
   349→      <Animated.View
   350→        style={[styles.audioControlsContainer, audioControlsAnimatedStyle]}
   351→        pointerEvents={isUIVisible ? 'auto' : 'none'}
   352→      >
   353→        <AudioControls
   354→          hasNarration={!!narrationUrl}
   355→          hasSoundscape={!!soundscapeUrl}
   356→          isNarrationPlaying={isNarrationActive && narrationState.isPlaying}
   357→          isSoundscapePlaying={isSoundscapeActive && soundscapeState.isPlaying}
   358→          onToggleNarration={toggleNarration}
   359→          onToggleSoundscape={toggleSoundscape}
   360→        />
   361→      </Animated.View>
   362→
   363→      <SwipePageIndicator visible={isUIVisible && activeIndex === 0 && totalPages > 1} />
   364→
   365→      {/* Edge Tap Zones - only visible when UI is hidden */}
   366→      {!isUIVisible && (
   367→        <EdgeTapZones
   368→          onPrevious={goToPreviousPage}
   369→          onNext={goToNextPage}
   370→          isVisible={!isUIVisible}
   371→        />
   372→      )}
   373→
   374→      {/* Tap hint when UI is hidden */}
   375→      <Animated.View style={[styles.tapHintContainer, tapHintAnimatedStyle]} pointerEvents="none">
   376→        <Text style={[styles.tapHintText, { color: colors.readerTextSecondary }]}>
   377→          Tap to show controls
   378→        </Text>
   379→      </Animated.View>
   380→
   381→      <GestureTutorial
   382→        visible={showTutorial}
   383→        onComplete={handleTutorialComplete}
   384→      />
   385→    </View>
   386→  );
   387→}
