     1→import { useState, useEffect, useCallback } from 'react';
     2→import { getPreferences, setPreferences } from '@/lib/storage';
     3→import type { ReaderPreferences, SoundscapeMode } from '@/types';
     4→
     5→const STORAGE_KEY = 'storia-reader-preferences';
     6→
     7→const defaultPreferences: ReaderPreferences = {
     8→  soundscapeMode: 'continuous',
     9→  soundscapeEnabled: true,
    10→  hasSeenNavigationHint: false,
    11→};
    12→
    13→export function useLocalPreferences() {
    14→  const [preferences, setPrefs] = useState<ReaderPreferences>(defaultPreferences);
    15→  const [isLoaded, setIsLoaded] = useState(false);
    16→
    17→  useEffect(() => {
    18→    getPreferences<ReaderPreferences>(STORAGE_KEY).then((stored) => {
    19→      if (stored) {
    20→        setPrefs({ ...defaultPreferences, ...stored });
    21→      }
    22→      setIsLoaded(true);
    23→    });
    24→  }, []);
    25→
    26→  const savePreferences = useCallback((updates: Partial<ReaderPreferences>) => {
    27→    setPrefs((prev) => {
    28→      const next = { ...prev, ...updates };
    29→      setPreferences(next, STORAGE_KEY);
    30→      return next;
    31→    });
    32→  }, []);
    33→
    34→  const setSoundscapeMode = useCallback(
    35→    (mode: SoundscapeMode) => savePreferences({ soundscapeMode: mode }),
    36→    [savePreferences]
    37→  );
    38→
    39→  const setSoundscapeEnabled = useCallback(
    40→    (enabled: boolean) => savePreferences({ soundscapeEnabled: enabled }),
    41→    [savePreferences]
    42→  );
    43→
    44→  const setHasSeenNavigationHint = useCallback(
    45→    (seen: boolean) => savePreferences({ hasSeenNavigationHint: seen }),
    46→    [savePreferences]
    47→  );
    48→
    49→  return {
    50→    preferences,
    51→    isLoaded,
    52→    setSoundscapeMode,
    53→    setSoundscapeEnabled,
    54→    setHasSeenNavigationHint,
    55→  };
    56→}
