     1→import { useCallback } from 'react';
     2→import { Dimensions } from 'react-native';
     3→import { useAnimatedStyle, SharedValue } from 'react-native-reanimated';
     4→
     5→const { height: SCREEN_HEIGHT } = Dimensions.get('window');
     6→
     7→export function usePageAnimatedStyle(
     8→  translateY: SharedValue<number>,
     9→  activeIndexShared: SharedValue<number>
    10→) {
    11→  return useCallback((pageIndex: number) => {
    12→    return useAnimatedStyle(() => {
    13→      const idx = activeIndexShared.value;
    14→      const diff = pageIndex - idx;
    15→
    16→      if (diff === 0) {
    17→        // Active page
    18→        return {
    19→          transform: [{ translateY: translateY.value }],
    20→          opacity: 1,
    21→          zIndex: 2,
    22→        };
    23→      } else if (diff === 1) {
    24→        // Next page (below, slides up)
    25→        const progress = Math.min(Math.max(-translateY.value / SCREEN_HEIGHT, 0), 1);
    26→        return {
    27→          transform: [
    28→            { translateY: SCREEN_HEIGHT * (1 - progress) },
    29→          ],
    30→          opacity: 1,
    31→          zIndex: 3,
    32→        };
    33→      } else if (diff === -1) {
    34→        // Previous page (above, drifts up when swiping down)
    35→        const progress = Math.min(Math.max(translateY.value / SCREEN_HEIGHT, 0), 1);
    36→        return {
    37→          transform: [
    38→            { translateY: -SCREEN_HEIGHT * 0.2 * (1 - progress) },
    39→          ],
    40→          opacity: 0.4 + 0.6 * progress,
    41→          zIndex: 1,
    42→        };
    43→      }
    44→
    45→      // Off-screen
    46→      return {
    47→        transform: [{ translateY: diff > 0 ? SCREEN_HEIGHT : -SCREEN_HEIGHT }],
    48→        opacity: 0,
    49→        zIndex: 0,
    50→      };
    51→    });
    52→  }, [translateY, activeIndexShared]);
    53→}
